INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Centralised clearance (KSeF)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. KSeF 2.0 API details, authentication requirements, and the pending Article 106ni amendment continue to evolve — confirm current requirements directly on the Ministry of Finance''s KSeF portal before building an integration.', 'KSeF has been rebuilt once already — Poland paused an earlier version after a technical audit found the architecture needed strengthening. KSeF 2.0 is the version that actually went live.', 'FA(3) is the third generation of Poland''s national schema — each revision has tightened validation and added more structured detail than the last.', 'KSeF is a true clearance model: the buyer retrieves the invoice from the central system rather than receiving it directly from the seller.', 'Access setup is a one-time process centred on a single authorisation form and your choice of authentication credential.', 'Poland''s penalty regime is among the strictest in Europe on paper — but a full-year grace period and a planned legislative clarification soften the picture considerably.' FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'FA(3)', 'Current invoice schema');
