INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '100%', 'Max penalty (% of VAT)');
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2027', 'Full enforcement begins');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Schema', '[["Current version", "FA(3) (replaced FA(2), 1 Feb 2026)"], ["Alignment", "EN 16931 semantic model, Peppol BIS conventions"], ["New in FA(3)", "New VAT rate codes, attachment support, dates from 1990"]]', 'FA(3) was shaped directly by tax consultations with entrepreneurs, accountants, auditors, and IT vendors — the attachment support in particular was a direct response to feedback that FA(2) was too rigid for real-world invoicing scenarios.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content', '[["Identifiers", "Supplier & customer NIP"], ["Transaction detail", "Itemised lines, VAT rates and amounts, totals, currency"], ["Legal remarks", "Reverse-charge and other required indicators"], ["Digital signature", "Not required from suppliers"]]', 'Suppliers don''t apply their own qualified signature — KSeF''s own clearance process (validation, sealing, and reference number assignment) is what gives the invoice legal force, similar in spirit to Italy''s SDI model.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Clearance output', '[["Reference number", "Unique KSeF number, assigned on validation"], ["Receipt", "UPO (Urz\u0119dowe Po\u015bwiadczenie Odbioru) confirmation"], ["Verification", "QR code linking to the central system"]]', 'An invoice without a valid KSeF number is not valid for tax purposes — this is the sharpest practical difference from decentralised models like Germany''s, where the file itself carries legal weight without a central clearance step.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Archiving', '[["Central retention", "10 years from year-end of issuance"], ["Standard PL retention", "5 years (KSeF doubles this)"]]', 'Because KSeF stores every validated invoice centrally for 10 years, businesses don''t need to independently archive invoice XML files for compliance purposes — a genuine operational simplification compared to decentralised regimes.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'API', '[["Specification", "OpenAPI 3.0.4"], ["SDKs", ".NET and Java, with sample code"], ["Submission modes", "Interactive and batch"]]', 'Test thoroughly in the sandbox environment before connecting to production — the API documentation includes full endpoint, parameter, and response-code references specifically to support this.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Authentication methods', '[["Qualified electronic seal", "Containing the taxpayer''s NIP"], ["KSeF certificate", "Via the Certificates and Authorizations Module (MCU)"], ["Token", "Available until end of 2026 only"], ["Trusted Profile", "Eliminated from 1 Apr 2026"]]', 'Plan your long-term authentication approach around qualified seals or KSeF certificates — tokens and the Trusted Profile route are both being phased out on different timelines.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Buyer workflow', '[["Delivery model", "Retrieval from KSeF, not direct send"], ["Domestic NIP recipients", "Receive exclusively through KSeF post-clearance"], ["Non-KSeF recipients (offline delivery)", "Require dual QR codes before submission"]]', 'This buyer-retrieves-rather-than-receives model is the key structural difference from Peppol-based countries — there''s no "delivery" step in the conventional sense once an invoice clears KSeF.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🕊️ Full 2026 grace period', NULL, NULL, 'No financial penalties apply for KSeF errors throughout the entirety of 2026, regardless of when a given business''s mandatory start date falls — enforcement genuinely begins on 1 January 2027, not before.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ Planned legislative fix', NULL, NULL, 'The Ministry of Finance has acknowledged a "redundant reference" in Article 106ni and plans to amend the VAT Act before the January 2027 deadline, so that penalties apply only to deliberate KSeF avoidance — not incidental errors during a functioning system.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 Narrow ongoing exceptions', NULL, NULL, '"Digitally excluded" taxpayers — those genuinely unable to access digital infrastructure, with transactions under PLN 450 per invoice and PLN 10,000 total monthly sales — retain an exception even after January 2027.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Assess your system''s FA(3) and API compatibility', 'Check your invoicing or ERP software against the FA(3) logical structure and KSeF 2.0 API documentation, or plan to use the Ministry''s free tools if you don''t have in-house development capacity.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'File the ZAW-FA authorisation form', 'This names the person authorised to operate KSeF on your entity''s behalf. It''s not required if you hold a qualified electronic seal containing your NIP — in that case you can use KSeF directly. The person named in ZAW-FA can then grant further authorisations to others directly within the platform.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Obtain your authentication credential', 'Apply for a KSeF certificate via the Certificates and Authorizations Module, or use a token during the transitional period (available only until the end of 2026). Every authorised person needs a NIP or PESEL, or a qualified electronic signature if they have neither.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Test in the sandbox before going live', 'Use the KSeF 2.0 test environment to pilot invoice submission, receipt retrieval, and error handling — this is where most integration problems surface, well before they hit production.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up delegation for third-party providers', 'If an accountant or external service handles invoicing for you, configure their authorisation and delegation rules explicitly rather than sharing your own credentials.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Build offline24 handling into your pipeline', 'Implement the ability to issue structured invoices outside KSeF during downtime, generate the required QR code, and submit to KSeF no later than the next business day.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://ksef.mf.gov.pl/', 0 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'KSeF — Ministry of Finance');
