INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Invoice with VAT shown, issued outside KSeF', 'Up to 100% of the VAT amount on the invoice', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Invoice with no VAT shown, issued outside KSeF', 'Up to 18.7% of the total amount due', '—');
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Payment deadline once a decision is issued', '14 days, no summons required', '—');
INSERT INTO deep_dive_lifecycle_intro (country_id) SELECT id FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_lifecycle_intro_translations (country_id, lang, title, intro_text, outro_text) SELECT id, 'en', 'Offline modes & QR codes', 'Four offline modes exist for when KSeF itself is unavailable or unreachable:', 'Invoices issued offline or in failure mode need a QR code for verification, and must be submitted to KSeF by the next working day. Domestic NIP-holders no longer need a QR code on the printout itself — they retrieve the legally valid invoice through KSeF directly, except in failure mode.' FROM countries WHERE name_en = 'Poland';
