INSERT INTO deep_dive_lifecycle_status_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses), 'en', 'Offline24');
INSERT INTO deep_dive_lifecycle_statuses (country_id, sort_order, is_special) SELECT id, 1, 0 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_lifecycle_status_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses), 'en', 'Standard offline');
INSERT INTO deep_dive_lifecycle_statuses (country_id, sort_order, is_special) SELECT id, 2, 0 FROM countries WHERE name_en = 'Poland';
INSERT INTO deep_dive_lifecycle_status_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses), 'en', 'Failure mode');
